package com.elogistic.backend.workflow.internal.web;

import com.elogistic.backend.merchant.api.customer.OrganizationContacts;
import com.elogistic.backend.merchant.api.customer.OrganizationContacts.*;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.net.URI;
import java.util.*;
import java.util.function.Function;
import org.springframework.context.annotation.Profile;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static com.elogistic.backend.workflow.internal.web.BusinessPreparationHttp.*;
import static com.elogistic.backend.workflow.internal.web.CustomerProfileHttp.problem;

@RestController @Profile("customer")
public final class OrganizationContactsHttp {
    private static final String BASE="/api/v1/merchant-organizations/{organizationId}";
    private static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
    private final BusinessPreparationHttp admission;private final OrganizationContacts contacts;private final com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers transfers;
    public OrganizationContactsHttp(BusinessPreparationHttp admission,OrganizationContacts contacts,com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers transfers){this.admission=admission;this.contacts=contacts;this.transfers=transfers;}
    @ModelAttribute public void noStore(jakarta.servlet.http.HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
    private <T>T execute(String org,Function<Access,T> work){try{return admission.execute(org,a->work.apply(new Access(){public UUID actorAccountId(){return a.actorAccountId();}public UUID requestId(){return a.requestId();}public com.elogistic.backend.merchant.api.customer.BusinessWorkspaces.Scope scope(){return a.scope();}public void requireCurrent(){a.requireCurrent();}public void meaningfulAction(){a.meaningfulAction();}}));}catch(OrganizationContacts.Failure rejected){throw problem(switch(rejected.getMessage()){case "VALIDATION_FAILED"->400;case "RESOURCE_NOT_FOUND"->404;case "IDEMPOTENCY_CONFLICT","PRECONDITION_STALE","CONTACT_REFERENCE_CONFLICT","CONTACT_STATE_CONFLICT","CONTACT_BINDING_IMMUTABLE","IMPORT_ROW_NOT_VALID"->409;case "EXPORT_LIMIT_EXCEEDED"->422;default->503;},rejected.getMessage());}}
    private static Map<String,String> params(HttpServletRequest r,Set<String> allowed){var values=new HashMap<String,String>();r.getParameterMap().forEach((k,v)->{if(!allowed.contains(k)||v.length!=1)throw problem(400,"VALIDATION_FAILED");values.put(k,v[0]);});return values;}
    private static Query query(Map<String,String> p,String search,String group){return new Query(number(p.get("page"),0),number(p.get("size"),20),search,p.get("kind"),p.get("state"),p.containsKey("facilityId")?uuid(p.get("facilityId")):null,group);}
    private static JsonNode body(HttpServletRequest r)throws IOException{return body(r,8192);}
    private static JsonNode body(HttpServletRequest r,int limit)throws IOException{if(r.getContentType()==null||!r.getContentType().split(";",2)[0].equalsIgnoreCase("application/json"))throw problem(400,"VALIDATION_FAILED");byte[] bytes=r.getInputStream().readNBytes(limit+1);try{if(bytes.length>limit)throw problem(400,"VALIDATION_FAILED");return JSON.readTree(bytes);}catch(RuntimeException bad){throw problem(400,"VALIDATION_FAILED");}finally{Arrays.fill(bytes,(byte)0);}}
    private static Input input(JsonNode v){shape(v,Set.of("kind","contactName","contactPhone","address"),Set.of("kind","facilityId","label","reference","group","contactName","contactPhone","address"));for(String k:List.of("kind","contactName","contactPhone"))if(!v.get(k).isString())throw problem(400,"VALIDATION_FAILED");for(String k:List.of("label","reference","group"))if(v.has(k)&&!v.get(k).isNull()&&!v.get(k).isString())throw problem(400,"VALIDATION_FAILED");if(v.has("facilityId")&&!v.get("facilityId").isNull()){if(!v.get("facilityId").isString())throw problem(400,"VALIDATION_FAILED");uuid(v.get("facilityId").asString());}var a=v.get("address");var fields=Set.of("country","administrativeArea","locality","addressLine");shape(a,fields,fields);for(String k:fields)if(!a.get(k).isString())throw problem(400,"VALIDATION_FAILED");try{return JSON.treeToValue(v,Input.class);}catch(RuntimeException bad){throw problem(400,"VALIDATION_FAILED");}}
    private static ResponseEntity<Contact> response(Contact c){return ResponseEntity.ok().eTag("\"v"+c.version()+"\"").body(c);}
    @GetMapping(BASE+"/contacts") public Page list(@PathVariable String organizationId,HttpServletRequest r){var q=query(params(r,Set.of("page","size","kind","state","facilityId")),null,null);return execute(organizationId,a->contacts.list(a,q));}
    @PostMapping(BASE+"/contacts/search") public Page search(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());var v=body(r);shape(v,Set.of("page","size","search"),Set.of("page","size","search","kind","state","facilityId","group"));if(!v.get("page").isIntegralNumber()||!v.get("page").canConvertToInt()||!v.get("size").isIntegralNumber()||!v.get("size").canConvertToInt()||!v.get("search").isString())throw problem(400,"VALIDATION_FAILED");var p=new HashMap<String,String>();p.put("page",Integer.toString(v.get("page").asInt()));p.put("size",Integer.toString(v.get("size").asInt()));for(String k:List.of("kind","state","facilityId","group")){if(v.has(k)&&!v.get(k).isString())throw problem(400,"VALIDATION_FAILED");if(v.has(k))p.put(k,v.get(k).asString());}var q=query(p,v.get("search").asString(),p.get("group"));return execute(organizationId,a->contacts.list(a,q));}
    @PostMapping(BASE+"/contacts") public ResponseEntity<Contact> create(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());UUID key=key(r);var in=input(body(r));var c=execute(organizationId,a->contacts.create(a,in,key));return ResponseEntity.created(URI.create("/api/v1/merchant-organizations/"+c.organizationId()+"/contacts/"+c.id())).eTag("\"v"+c.version()+"\"").body(c);}
    @GetMapping(BASE+"/contacts/{id}") public ResponseEntity<Contact> get(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){params(r,Set.of());UUID target=uuid(id);return response(execute(organizationId,a->contacts.get(a,target)));}
    @PutMapping(BASE+"/contacts/{id}") public ResponseEntity<Contact> update(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID target=uuid(id),key=key(r);long version=version(r);var in=input(body(r));return response(execute(organizationId,a->contacts.update(a,target,in,version,key)));}
    @PostMapping({BASE+"/contacts/{id}/archive",BASE+"/contacts/{id}/restore"}) public ResponseEntity<Contact> lifecycle(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID target=uuid(id),key=key(r);long version=version(r);if(r.getInputStream().read()!=-1)throw problem(400,"VALIDATION_FAILED");boolean restore=r.getRequestURI().endsWith("/restore");return response(execute(organizationId,a->restore?contacts.restore(a,target,version,key):contacts.archive(a,target,version,key)));}
    @PostMapping(BASE+"/contact-duplicates") public Page duplicates(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());var v=body(r);shape(v,Set.of("input"),Set.of("input"));var in=input(v.get("input"));return execute(organizationId,a->contacts.duplicates(a,in));}
    private static ResponseEntity<Default> defaultResponse(Default d){return ResponseEntity.ok().eTag("\"d"+d.version()+"\"").body(d);}
    @GetMapping(BASE+"/contact-defaults") public ResponseEntity<Default> defaultContact(@PathVariable String organizationId,HttpServletRequest r){var p=params(r,Set.of("kind","facilityId"));return defaultResponse(execute(organizationId,a->contacts.defaultContact(a,p.get("kind"),p.containsKey("facilityId")?uuid(p.get("facilityId")):null)));}
    @PutMapping(BASE+"/contact-defaults") public ResponseEntity<Default> setDefault(@PathVariable String organizationId,HttpServletRequest r)throws IOException{var p=params(r,Set.of("kind","facilityId"));UUID key=key(r);var h=Collections.list(r.getHeaders("If-Match"));long version;try{if(h.size()!=1||!h.getFirst().matches("\"d(?:0|[1-9][0-9]{0,18})\""))throw problem(428,"PRECONDITION_REQUIRED");version=Long.parseLong(h.getFirst().substring(2,h.getFirst().length()-1));}catch(NumberFormatException bad){throw problem(400,"VALIDATION_FAILED");}var v=body(r);shape(v,Set.of("contactId"),Set.of("contactId"));if(!v.get("contactId").isNull()&&!v.get("contactId").isString())throw problem(400,"VALIDATION_FAILED");UUID target=v.get("contactId").isNull()?null:uuid(v.get("contactId").asString());return defaultResponse(execute(organizationId,a->contacts.setDefault(a,p.get("kind"),p.containsKey("facilityId")?uuid(p.get("facilityId")):null,target,version,key)));}
    @GetMapping(BASE+"/contact-receipts/{operation}/{key}") public Receipt receipt(@PathVariable String organizationId,@PathVariable String operation,@PathVariable String key,HttpServletRequest r){params(r,Set.of());return execute(organizationId,a->contacts.receipt(a,operation,uuid(key)));}
    @PostMapping(BASE+"/contact-imports") public com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.Job preview(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());UUID key=key(r);var v=body(r,1048576);shape(v,Set.of("templateVersion","facilityId","csv"),Set.of("templateVersion","facilityId","csv"));if(!v.get("templateVersion").isString()||!v.get("csv").isString()||!v.get("facilityId").isNull()&&!v.get("facilityId").isString())throw problem(400,"VALIDATION_FAILED");UUID facility=v.get("facilityId").isNull()?null:uuid(v.get("facilityId").asString());var job=execute(organizationId,a->transfers.preview(a,v.get("templateVersion").asString(),facility,v.get("csv").asString(),key));return job;}
    @GetMapping(BASE+"/contact-imports") public com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.Page imports(@PathVariable String organizationId,HttpServletRequest r){var p=params(r,Set.of("page","size"));if(number(p.get("size"),20)!=20)throw problem(400,"VALIDATION_FAILED");return execute(organizationId,a->transfers.list(a,number(p.get("page"),0)));}
    @GetMapping(BASE+"/contact-imports/{id}") public ResponseEntity<com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.Job> importJob(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){var p=params(r,Set.of("page","size"));if(number(p.get("size"),20)!=20)throw problem(400,"VALIDATION_FAILED");var job=execute(organizationId,a->transfers.get(a,uuid(id),number(p.get("page"),0)));return ResponseEntity.ok().eTag("\"v"+job.version()+"\"").body(job);}
    @PostMapping(BASE+"/contact-imports/{id}/commit") public ResponseEntity<com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.Job> commit(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID key=key(r),target=uuid(id);long version=version(r);var v=body(r);shape(v,Set.of("rows"),Set.of("rows"));var rows=v.get("rows");if(!rows.isArray()||rows.isEmpty()||rows.size()>20)throw problem(400,"VALIDATION_FAILED");List<Integer> selected=new ArrayList<>();for(var n:rows){if(!n.isIntegralNumber()||!n.canConvertToInt())throw problem(400,"VALIDATION_FAILED");selected.add(n.asInt());}var job=execute(organizationId,a->transfers.commit(a,target,selected,version,key));return ResponseEntity.ok().eTag("\"v"+job.version()+"\"").body(job);}
    @PostMapping(BASE+"/contact-exports") public com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.Export export(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());var v=body(r);shape(v,Set.of(),Set.of("search","kind","state","facilityId","group"));var values=new HashMap<String,String>();for(var field:v.properties()){if(!field.getValue().isString())throw problem(400,"VALIDATION_FAILED");values.put(field.getKey(),field.getValue().asString());}var q=query(values,values.get("search"),values.get("group"));return execute(organizationId,a->transfers.export(a,q));}

}
